const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0];
const x = new Int32Array(N);
const y = new Int32Array(N);
for (let i = 0; i < N; i++) {
  x[i] = data[1 + 2 * i];
  y[i] = data[2 + 2 * i];
}

const M = N * N;
const edges = new Float64Array(M);
let idx = 0;
const SHIFT = 11;
const MASK = (1 << SHIFT) - 1;
const MULT = 1 << 22;
const BASE = 1000000000;

for (let u = 0; u <= N; u++) {
  for (let v = 0; v < N; v++) {
    if (u === v) continue;
    let dx, dy;
    if (u === N) {
      dx = x[v];
      dy = y[v];
    } else {
      dx = x[u] - x[v];
      dy = y[u] - y[v];
    }
    const weight = dx * dx + dy * dy;
    const uv = (u << SHIFT) | v;
    const key = (BASE - weight) * MULT + uv;
    edges[idx++] = key;
  }
}

edges.sort();

const best = new Int32Array(N);
const groupBest = new Int32Array(N);
const modified = new Int32Array(N);
let modCount = 0;
let answer = 0;

let i = 0;
while (i < M) {
  const key = edges[i];
  const weightHigh = Math.floor(key / MULT);
  let j = i;
  while (j < M) {
    const k = edges[j];
    const wh = Math.floor(k / MULT);
    if (wh !== weightHigh) break;
    const uv = k - wh * MULT;
    const u = uv >> SHIFT;
    const v = uv & MASK;
    let dp = 0;
    if (u === N) {
      dp = 1;
    } else if (best[u] > 0) {
      dp = best[u] + 1;
    }
    if (dp > 0) {
      if (dp > groupBest[v]) {
        if (groupBest[v] === 0) {
          modified[modCount++] = v;
        }
        groupBest[v] = dp;
      }
      if (dp > answer) answer = dp;
    }
    j++;
  }
  for (let t = 0; t < modCount; t++) {
    const v = modified[t];
    if (groupBest[v] > best[v]) best[v] = groupBest[v];
    groupBest[v] = 0;
  }
  modCount = 0;
  i = j;
}

console.log(answer);
